package com.boutique.shipping.messaging;import com.boutique.shipping.entity.ShippingOutboxEvent;import com.boutique.shipping.repository.ShippingOutboxRepository;import tools.jackson.databind.ObjectMapper;import org.springframework.stereotype.Component;import java.time.Instant;import java.util.*;
@Component public class ShipmentEventPublisher{private final ShippingOutboxRepository outbox;private final ObjectMapper json;public ShipmentEventPublisher(ShippingOutboxRepository o,ObjectMapper j){outbox=o;json=j;}public void created(UUID shipmentId,UUID orderId){try{Map<String,Object>e=new LinkedHashMap<>();e.put("eventId",UUID.randomUUID());e.put("eventType","SHIPMENT_CREATED");e.put("shipmentId",shipmentId);e.put("orderId",orderId);e.put("status","CREATED");e.put("occurredAt",Instant.now());outbox.save(new ShippingOutboxEvent(orderId,"SHIPMENT_CREATED",json.writeValueAsString(e)));}catch(Exception ex){throw new IllegalStateException("Shipment event outbox serialization failed",ex);}}}
